      "svg": "<svg viewBox=\"0 0 1100 1100\">\n      <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n      <text x=\"550\" y=\"75\" font-size=\"28\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Diagnose the Break</text>\n      <circle cx=\"250\" cy=\"260\" r=\"80\" fill=\"#10b981\" opacity=\"0.85\"/>\n      <text x=\"250\" y=\"265\" font-size=\"16\" fill=\"#1a1a2e\" text-anchor=\"middle\" font-weight=\"bold\">/us/product</text>\n      <circle cx=\"550\" cy=\"200\" r=\"80\" fill=\"#0ea5e9\" opacity=\"0.85\"/>\n      <text x=\"550\" y=\"205\" font-size=\"16\" fill=\"#1a1a2e\" text-anchor=\"middle\" font-weight=\"bold\">/uk/product</text>\n      <circle cx=\"850\" cy=\"260\" r=\"80\" fill=\"#8b5cf6\" opacity=\"0.85\"/>\n      <text x=\"850\" y=\"265\" font-size=\"16\" fill=\"#ffffff\" text-anchor=\"middle\" font-weight=\"bold\">/de/produkt</text>\n      <circle cx=\"550\" cy=\"420\" r=\"80\" fill=\"#ef4444\" opacity=\"0.9\"/>\n      <text x=\"550\" y=\"415\" font-size=\"16\" fill=\"#ffffff\" text-anchor=\"middle\" font-weight=\"bold\">/fr/produit-NEW</text>\n      <text x=\"550\" y=\"440\" font-size=\"13\" fill=\"#ffffff\" text-anchor=\"middle\">(moved, not updated)</text>\n      <line x1=\"250\" y1=\"260\" x2=\"550\" y2=\"200\" stroke=\"#888\" stroke-width=\"2\"/>\n      <line x1=\"250\" y1=\"260\" x2=\"850\" y2=\"260\" stroke=\"#888\" stroke-width=\"2\"/>\n      <line x1=\"550\" y1=\"200\" x2=\"850\" y2=\"260\" stroke=\"#888\" stroke-width=\"2\"/>\n      <line x1=\"250\" y1=\"260\" x2=\"550\" y2=\"420\" stroke=\"#ef4444\" stroke-width=\"3\" stroke-dasharray=\"8,6\"/>\n      <line x1=\"550\" y1=\"200\" x2=\"550\" y2=\"420\" stroke=\"#ef4444\" stroke-width=\"3\" stroke-dasharray=\"8,6\"/>\n      <line x1=\"850\" y1=\"260\" x2=\"550\" y2=\"420\" stroke=\"#ef4444\" stroke-width=\"3\" stroke-dasharray=\"8,6\"/>\n      <text x=\"550\" y=\"545\" font-size=\"16\" fill=\"#ef4444\" text-anchor=\"middle\">Dashed = pointing to stale, now-incorrect URL</text>\n      <rect x=\"130\" y=\"600\" width=\"840\" height=\"140\" rx=\"12\" fill=\"#1a1a2e\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n      <text x=\"550\" y=\"645\" font-size=\"19\" fill=\"#f59e0b\" text-anchor=\"middle\" font-weight=\"bold\">Missing: x-default fallback</text>\n      <text x=\"550\" y=\"680\" font-size=\"15\" fill=\"#ffffff\" text-anchor=\"middle\">A visitor searching in Japanese has no defined page</text>\n      <text x=\"550\" y=\"710\" font-size=\"15\" fill=\"#ffffff\" text-anchor=\"middle\">and search engines must guess which variant to show</text>\n      <rect x=\"130\" y=\"780\" width=\"840\" height=\"150\" rx=\"12\" fill=\"#1a1a2e\" stroke=\"#10b981\" stroke-width=\"2\"/>\n      <text x=\"550\" y=\"825\" font-size=\"18\" fill=\"#10b981\" text-anchor=\"middle\" font-weight=\"bold\">Fix: update ALL reciprocal references</text>\n      <text x=\"550\" y=\"860\" font-size=\"15\" fill=\"#ffffff\" text-anchor=\"middle\">every time any single URL in the cluster changes,</text>\n      <text x=\"550\" y=\"890\" font-size=\"15\" fill=\"#ffffff\" text-anchor=\"middle\">and always declare one page as x-default</text>\n    </svg>",
